// ===== 운동 사전 (기본 내장) =====
const MN={chest:'대흉근(가슴)',delts:'삼각근(어깨)',biceps:'상완이두근',triceps:'상완삼두근',forearms:'전완근',abs:'복직근',obliques:'복사근',traps:'승모근·능형근',lats:'광배근',lowerback:'척추기립근',glutes:'둔근(엉덩이)',quads:'대퇴사두근',hamstrings:'햄스트링',adductors:'내전근',calves:'종아리'};
const EXCATS=["가슴", "등", "어깨", "이두", "삼두", "전완", "하체", "엉덩이", "종아리", "코어", "전신"];
const EX=[{"id":"bench","n":"벤치프레스","en":"Bench Press","eq":"바벨","a":"대흉근이 팔을 몸 중앙으로 모으는 수평 내전과 어깨 굴곡을 만들어 바를 밀어 올립니다. 전면 삼각근이 어깨 굴곡을 돕고, 상완삼두근이 팔꿈치를 펴며(신전) 동작을 마무리합니다. 견갑골을 모아 고정하면 대흉근이 늘어난 상태에서 힘을 낼 수 있어 자극은 커지고 어깨 관절 부담은 줄어듭니다.","u":"무거운 문 밀기, 카트 밀기, 넘어질 때 팔로 몸 받치기 같은 \"미는 힘\"의 기본입니다. 상체 미는 근력의 기준 운동입니다.","st":["벤치에 누워 눈이 바 바로 아래에 오도록 위치","어깨너비보다 조금 넓게 바를 잡고 견갑골을 뒤·아래로 모음","발바닥 전체로 바닥을 누르고 가슴을 살짝 들어 아치","숨을 들이쉬며 바를 가슴 아래쪽(명치 위)으로 천천히 내림","팔꿈치는 몸통과 약 45~70°를 유지","가슴에 닿기 직전 숨을 내쉬며 밀어 올림"],"c":["엉덩이가 벤치에서 뜨지 않게","손목이 뒤로 꺾이지 않도록 바를 손바닥 아래쪽에 올림","고중량은 반드시 보조자나 세이프티바와 함께"],"cat":"가슴","p":["chest"],"s":["delts","triceps"]},
{"id":"incbb","n":"인클라인 바벨 프레스","en":"Incline Barbell Press","eq":"바벨·인클라인 벤치","a":"벤치를 30~45° 세우면 대흉근 윗부분(쇄골부)과 전면 삼각근의 비중이 커집니다. 바를 쇄골 아래로 내렸다가 수직으로 밀어 올립니다.","st":["벤치 각도 30~45°로 맞추고 견갑골을 모아 등을 고정","어깨너비보다 조금 넓게 바를 잡음","바를 쇄골 아래 윗가슴으로 천천히 내림","가슴을 편 채 수직으로 밀어 올림"],"c":["각도가 너무 높으면 어깨 운동이 됨","허리를 과하게 띄우지 않기"],"cat":"가슴","p":["chest"],"s":["delts","triceps"]},
{"id":"declbb","n":"디클라인 벤치프레스","en":"Decline Bench Press","eq":"바벨·디클라인 벤치","a":"머리가 낮은 자세라 대흉근 아랫부분(복장늑골부)이 주로 일합니다. 어깨 부담이 적어 무게를 다루기 좋습니다.","st":["발목을 패드에 고정하고 누움","어깨너비보다 넓게 바를 잡음","바를 가슴 아래쪽으로 내림","팔꿈치를 펴며 밀어 올림"],"c":["머리로 피가 쏠리니 세트 사이 천천히 일어나기","보조자와 함께"],"cat":"가슴","p":["chest"],"s":["triceps","delts"]},
{"id":"dbpress","n":"덤벨 벤치프레스","en":"Dumbbell Bench Press","eq":"덤벨·벤치","a":"바벨보다 가동범위가 넓고 좌우가 따로 움직여, 가슴이 더 깊게 늘어나고 좌우 불균형을 바로잡기 좋습니다.","st":["덤벨을 무릎에 올렸다가 누우며 가슴 위로 가져옴","견갑골을 모으고 손목은 일직선","덤벨을 가슴 옆까지 천천히 내림","살짝 모으듯 밀어 올림"],"c":["내릴 때 팔꿈치가 어깨보다 너무 내려가지 않게","마지막에 덤벨을 서로 부딪치지 않기"],"cat":"가슴","p":["chest"],"s":["delts","triceps"]},
{"id":"incdb","n":"인클라인 덤벨프레스","en":"Incline Dumbbell Press","eq":"덤벨·벤치","a":"벤치를 30~45° 세우면 쇄골에 붙은 대흉근 윗부분(쇄골부)의 비중이 커집니다. 덤벨은 바벨보다 가동범위가 넓고 좌우가 따로 움직여 근력 불균형을 바로잡는 데 유리합니다.","u":"머리 위 선반에 물건을 밀어 올리기, 앞쪽 위로 미는 동작. 윗가슴을 채워 상체 라인을 개선합니다.","st":["벤치 각도 30~45°","덤벨을 허벅지에 올렸다가 눕는 반동으로 어깨 위에 위치","견갑골을 모으고 팔꿈치를 살짝 아래로","덤벨을 윗가슴 옆까지 천천히 내림","가슴을 모으는 느낌으로 위로 밀어 올림"],"c":["각도가 너무 높으면 어깨 운동이 됨","덤벨끼리 부딪치지 않게 위에서 멈춤"],"cat":"가슴","p":["chest"],"s":["delts","triceps"]},
{"id":"dbfly","n":"덤벨 플라이","en":"Dumbbell Fly","eq":"덤벨·벤치","a":"팔꿈치를 살짝 굽힌 채 팔을 크게 벌렸다 모으는 수평 내전 운동으로, 대흉근을 길게 늘여 자극합니다.","st":["덤벨을 가슴 위로 들고 손바닥이 마주 보게","팔꿈치를 살짝 굽힌 채 고정","가슴이 늘어나는 느낌까지 양옆으로 벌림","포옹하듯 원을 그리며 모음"],"c":["너무 무겁게 하면 어깨 부상 위험","팔꿈치 각도를 바꾸지 않기"],"cat":"가슴","p":["chest"],"s":["delts","biceps"]},
{"id":"incfly","n":"인클라인 덤벨 플라이","en":"Incline Dumbbell Fly","eq":"덤벨·인클라인 벤치","a":"인클라인 각도에서 플라이를 하면 윗가슴을 늘이며 자극할 수 있습니다.","st":["벤치 30° 정도로 세움","덤벨을 윗가슴 위로 들어 올림","팔꿈치를 살짝 굽힌 채 양옆으로 벌림","윗가슴을 모으듯 들어 올림"],"c":["반동 없이 천천히","어깨가 앞으로 말리지 않게"],"cat":"가슴","p":["chest"],"s":["delts"]},
{"id":"cablefly","n":"케이블 크로스오버","en":"Cable Crossover","eq":"케이블","a":"팔꿈치 각도를 고정한 채 팔을 모으는 순수한 수평 내전 동작이라 삼두근 개입이 적고 대흉근만 집중적으로 자극합니다. 케이블은 동작 끝까지 장력이 유지됩니다.","u":"팔로 무언가를 끌어안는 동작. 가슴 안쪽 라인과 근육의 모양을 다듬는 마무리 운동입니다.","st":["도르래를 어깨 높이 이상으로 맞추고 손잡이를 잡음","한 발 앞으로, 상체 살짝 숙임","팔꿈치를 살짝 굽힌 채 고정","큰 원을 그리며 손을 몸 앞에서 모음","가슴이 늘어나는 느낌으로 천천히 벌림"],"c":["팔꿈치를 굽혔다 폈다 하면 미는 운동이 됨","어깨가 앞으로 말리지 않게"],"cat":"가슴","p":["chest"],"s":["delts"]},
{"id":"lowfly","n":"로우 케이블 플라이","en":"Low Cable Fly","eq":"케이블","a":"낮은 곳에서 위로 모아 올리는 플라이로, 윗가슴(쇄골부)을 집중해서 자극합니다.","st":["케이블을 가장 낮게 두고 손잡이를 잡음","한 발 앞으로 내딛고 가슴을 폄","팔을 살짝 굽힌 채 아래에서 위로 모아 올림","턱 높이에서 모은 뒤 천천히 내림"],"c":["허리를 젖히지 않기","팔이 아닌 가슴으로 모으는 느낌"],"cat":"가슴","p":["chest"],"s":["delts","biceps"]},
{"id":"pecdeck","n":"펙덱 플라이","en":"Pec Deck Fly","eq":"머신","a":"팔꿈치를 패드에 대고 모으는 머신 플라이로, 궤적이 고정돼 초보자도 대흉근에 집중하기 쉽습니다.","st":["팔꿈치가 어깨 높이에 오도록 의자 높이 조절","등을 등받이에 붙이고 가슴을 폄","팔꿈치로 패드를 밀어 가운데로 모음","1초 정지 후 천천히 벌림"],"c":["어깨가 들리지 않게","너무 뒤로 벌리지 않기"],"cat":"가슴","p":["chest"],"s":["delts"]},
{"id":"chestpress","n":"체스트프레스 머신","en":"Machine Chest Press","eq":"머신","a":"앉아서 앞으로 미는 머신으로, 궤적이 안정적이라 벤치프레스를 배우기 전이나 마무리 운동으로 좋습니다.","st":["손잡이가 가슴 중앙 높이에 오도록 의자 조절","등을 붙이고 견갑골을 모음","숨을 내쉬며 앞으로 밀기","팔꿈치를 완전히 잠그지 말고 천천히 돌아옴"],"c":["어깨가 앞으로 나가지 않게","손목을 꺾지 않기"],"cat":"가슴","p":["chest"],"s":["triceps","delts"]},
{"id":"pushup","n":"푸시업","en":"Push-up","eq":"맨몸","a":"손이 바닥에 고정된 닫힌 사슬 운동으로 대흉근·삼두근이 몸을 밀어 올리고, 전거근과 복부·둔근이 몸을 일자로 버팁니다. 벤치프레스보다 어깨뼈가 자유롭게 움직여 어깨 건강에 좋습니다.","u":"바닥에서 일어나기, 몸을 밀어내는 모든 동작. 장소 제약 없는 상체 기본 근력 운동입니다.","st":["손은 어깨너비보다 약간 넓게","머리~발뒤꿈치 일직선, 엉덩이와 배에 힘","팔꿈치 45° 방향으로 굽히며 가슴을 바닥 가까이","바닥을 밀어내며 올라옴"],"c":["허리가 처지지 않게","힘들면 무릎을 대고 실시"],"cat":"가슴","p":["chest"],"s":["triceps","delts","abs"]},
{"id":"dips","n":"딥스","en":"Dips","eq":"평행봉","a":"몸을 앞으로 기울여 내려가면 대흉근 아랫부분, 몸을 세우면 삼두근 비중이 커집니다. 체중을 이용하는 고강도 운동입니다.","st":["평행봉을 잡고 팔을 펴 몸을 띄움","상체를 살짝 앞으로 기울임","팔꿈치가 90° 정도가 될 때까지 내려감","가슴으로 밀어 올리듯 올라옴"],"c":["어깨 통증이 있으면 깊이를 줄이기","반동 없이"],"cat":"가슴","p":["chest","triceps"],"s":["delts"]},
{"id":"pullover","n":"덤벨 풀오버","en":"Dumbbell Pullover","eq":"덤벨·벤치","a":"팔을 머리 뒤로 넘겼다가 가슴 위로 가져오는 동작으로, 대흉근과 광배근을 함께 늘이고 수축시킵니다.","st":["벤치에 누워 덤벨 한 개를 양손으로 받침","팔꿈치를 살짝 굽힌 채 머리 뒤로 천천히 내림","가슴과 옆구리가 늘어나는 느낌","가슴 위로 다시 들어 올림"],"c":["허리가 뜨지 않게 복부에 힘","너무 무겁게 하지 않기"],"cat":"가슴","p":["chest","lats"],"s":["triceps"]},
{"id":"smithbench","n":"스미스머신 벤치프레스","en":"Smith Machine Bench Press","eq":"스미스머신","a":"바가 레일을 따라 움직여 균형 부담 없이 가슴에 집중할 수 있습니다.","st":["바 아래 가슴 중앙이 오도록 누움","바를 돌려 걸쇠를 풀기","가슴까지 내렸다가 밀어 올림","끝나면 바를 돌려 걸기"],"c":["바 위치를 너무 목 쪽에 두지 않기","세이프티 높이 설정"],"cat":"가슴","p":["chest"],"s":["triceps","delts"]},
{"id":"latpull","n":"랫풀다운","en":"Lat Pulldown","eq":"머신","a":"광배근은 골반·척추 아래쪽에서 시작해 위팔뼈 앞쪽에 붙는 넓은 근육으로, 머리 위의 팔을 옆구리로 끌어내리는 어깨 내전·신전을 담당합니다. 하부 승모근과 능형근이 어깨뼈를 아래로 내리고 모으며(하강·후인), 이두근과 상완근이 팔꿈치 굽힘을 돕습니다.","u":"높은 곳의 물건 끌어내리기, 수영의 스트로크, 클라이밍, 턱걸이 준비. 굽은 어깨·라운드숄더 개선에 효과적입니다.","st":["패드에 허벅지를 고정하고 어깨너비의 1.5배로 바를 잡음","가슴을 들고 상체를 10~20° 뒤로 기울임","먼저 어깨를 아래로 내려 견갑골을 고정","팔꿈치를 옆구리 쪽으로 끌어내려 바를 쇄골~윗가슴까지","1초 멈춘 뒤 광배근이 늘어나는 느낌으로 천천히 올림"],"c":["반동으로 몸을 크게 젖히지 않기","목 뒤로 당기지 않기","손이 아니라 팔꿈치로 당긴다는 느낌"],"cat":"등","p":["lats"],"s":["biceps","traps","delts"]},
{"id":"closepull","n":"클로즈그립 랫풀다운","en":"Close-Grip Lat Pulldown","eq":"케이블 머신","a":"손 간격을 좁히면 광배근 아래쪽과 팔꿈치를 몸 옆으로 끌어내리는 동작이 강조됩니다.","st":["V바나 좁은 손잡이를 잡고 앉음","가슴을 들고 살짝 뒤로 기울임","팔꿈치를 옆구리로 끌어내리며 명치까지 당김","광배근이 늘어나도록 천천히 올림"],"c":["몸을 크게 젖히지 않기","팔로만 당기지 않기"],"cat":"등","p":["lats"],"s":["biceps","traps"]},
{"id":"pullup","n":"풀업(턱걸이)","en":"Pull-up","eq":"철봉","a":"랫풀다운과 같은 근육을 쓰지만 내 체중을 끌어올리는 닫힌 사슬 운동이라 코어 안정성과 전신 협응이 더 필요합니다.","u":"몸을 끌어올리는 모든 동작(담 넘기, 매달리기). 상체 당기는 근력의 대표 지표입니다.","st":["어깨너비보다 넓게 철봉을 잡고 매달림","어깨를 먼저 아래로 내림","가슴을 철봉 쪽으로 끌어올림","턱이 바를 넘으면 천천히 내려옴"],"c":["어려우면 밴드·어시스트 머신 사용","몸을 흔드는 키핑 금지"],"cat":"등","p":["lats"],"s":["biceps","traps","abs"]},
{"id":"chinup","n":"친업","en":"Chin-up","eq":"철봉","a":"손바닥이 나를 보게 잡고 매달리는 턱걸이로, 이두근 참여가 커서 풀업보다 조금 쉽습니다.","st":["어깨너비로 손바닥이 몸을 향하게 잡음","어깨를 내려 견갑골을 고정","가슴을 바 쪽으로 끌어올림","팔이 거의 펴질 때까지 천천히 내려옴"],"c":["다리 반동 쓰지 않기","목을 빼서 턱만 넘기지 않기"],"cat":"등","p":["lats","biceps"],"s":["traps"]},
{"id":"assistpull","n":"어시스트 풀업 머신","en":"Assisted Pull-up Machine","eq":"머신","a":"무릎 패드가 체중 일부를 받쳐 주는 머신으로, 턱걸이를 아직 못 하는 분이 동작을 익히기 좋습니다.","st":["보조 무게를 정하고 무릎을 패드에 올림","넓게 손잡이를 잡음","가슴을 들고 팔꿈치를 아래로 당김","천천히 내려옴"],"c":["보조 무게가 클수록 쉬움(일반 머신과 반대)","반동 없이"],"cat":"등","p":["lats"],"s":["biceps","traps"]},
{"id":"cablerow","n":"시티드 케이블 로우","en":"Seated Cable Row","eq":"케이블","a":"팔을 몸 쪽으로 당기는 어깨 신전과 어깨뼈를 모으는 후인 동작입니다. 광배근과 함께 등 가운데의 중부 승모근·능형근이 크게 쓰여 등의 두께를 만듭니다.","u":"문 당기기, 무거운 물건 끌어오기, 노 젓기. 앉아서 일하는 사람의 말린 어깨와 자세 교정에 좋습니다.","st":["발을 발판에 두고 무릎을 살짝 굽힘","허리를 곧게 세우고 손잡이를 잡음","가슴을 내밀며 손잡이를 명치 쪽으로 당김","견갑골을 끝까지 모으고 1초 정지","팔을 앞으로 펴며 등이 늘어나게 천천히 복귀"],"c":["상체를 앞뒤로 흔들지 않기","어깨가 귀 쪽으로 올라가지 않게"],"cat":"등","p":["lats","traps"],"s":["biceps","delts"]},
{"id":"bbrow","n":"바벨 로우","en":"Barbell Row","eq":"바벨","a":"상체를 숙인 자세에서 바를 배꼽 쪽으로 당겨 광배근·승모근·능형근을 강하게 씁니다. 숙인 자세를 버티기 위해 척추기립근과 햄스트링이 계속 등척성으로 일합니다.","u":"바닥의 짐을 들어 올려 몸 쪽으로 당기기. 등 전체 두께와 자세 유지 근력을 함께 기릅니다.","st":["어깨너비로 바를 잡고 엉덩이를 뒤로 빼며 상체를 30~45°까지 숙임","허리는 중립, 복부에 힘","바를 배꼽~아랫배 쪽으로 당김","견갑골을 모으고 천천히 내림"],"c":["허리가 둥글게 말리면 즉시 중량을 낮춤","반동 사용 금지"],"cat":"등","p":["lats","traps"],"s":["lowerback","biceps","hamstrings"]},
{"id":"dbrow","n":"원암 덤벨 로우","en":"One-Arm Dumbbell Row","eq":"덤벨·벤치","a":"한 손을 벤치에 짚어 몸통을 고정하고 한쪽씩 당겨, 광배근을 길게 쓰고 좌우 차이를 줄입니다.","st":["한 손과 같은 쪽 무릎(또는 손)을 벤치에 지지","등을 평평하게 유지","팔꿈치를 엉덩이 쪽으로 끌어 덤벨을 옆구리까지 당김","어깨가 늘어나도록 천천히 내림"],"c":["몸통을 비틀어 당기지 않기","허리가 둥글게 말리지 않게"],"cat":"등","p":["lats"],"s":["traps","biceps","delts"]},
{"id":"tbarrow","n":"티바 로우","en":"T-Bar Row","eq":"랜드마인·바벨","a":"바 한쪽을 고정하고 V핸들로 당기는 로우로, 고중량으로 등 두께(승모근·능형근·광배근)를 키우기 좋습니다.","st":["바를 다리 사이에 두고 V핸들을 잡음","엉덩이를 뒤로 빼 상체를 45° 정도 숙임","팔꿈치를 뒤로 당겨 원판이 가슴에 닿을 듯","천천히 내림"],"c":["허리 중립 유지","무릎을 살짝 굽혀 허리 부담 줄이기"],"cat":"등","p":["lats","traps"],"s":["biceps","lowerback"]},
{"id":"pendlay","n":"펜들레이 로우","en":"Pendlay Row","eq":"바벨","a":"상체를 바닥과 평행하게 두고 매 반복 바를 바닥에서 폭발적으로 당기는 로우로, 등 상부와 근력 향상에 좋습니다.","st":["상체를 바닥과 거의 평행하게 숙임","바닥에 놓인 바를 어깨너비보다 넓게 잡음","가슴 아래로 빠르게 당김","바를 바닥에 내려놓고 다시 시작"],"c":["상체가 들리며 반동 쓰지 않기","허리 중립"],"cat":"등","p":["lats","traps"],"s":["lowerback","biceps"]},
{"id":"machrow","n":"시티드 로우 머신","en":"Seated Row Machine","eq":"머신","a":"가슴을 패드에 대고 당기는 머신으로, 허리 부담 없이 등 가운데(능형근·중부 승모근)를 집중해서 쓸 수 있습니다.","st":["가슴 패드에 몸을 붙이고 손잡이를 잡음","어깨를 내리고 가슴을 폄","팔꿈치를 뒤로 당기며 견갑골을 모음","천천히 앞으로 보냄"],"c":["몸을 뒤로 젖혀 당기지 않기","어깨를 으쓱 올리지 않기"],"cat":"등","p":["lats","traps"],"s":["biceps","delts"]},
{"id":"straightpull","n":"스트레이트 암 풀다운","en":"Straight-Arm Pulldown","eq":"케이블","a":"팔을 편 채 위에서 허벅지까지 끌어내리는 동작으로, 이두근 개입 없이 광배근만 고립시킵니다.","st":["케이블 앞에서 엉덩이를 살짝 빼고 상체를 숙임","팔을 거의 편 채 바를 잡음","팔꿈치를 고정하고 허벅지까지 끌어내림","광배근이 늘어나도록 천천히 올림"],"c":["팔꿈치를 굽혀 당기지 않기","몸통 반동 금지"],"cat":"등","p":["lats"],"s":["triceps","abs"]},
{"id":"deadlift","n":"데드리프트","en":"Deadlift","eq":"바벨","a":"엉덩관절을 펴는 힙힌지 동작으로 대둔근과 햄스트링이 바를 들어 올리고, 척추기립근이 허리를 곧게 버팁니다. 무릎을 펴며 대퇴사두근이, 바를 쥐고 버티며 승모근과 전완근이 함께 일하는 전신 운동입니다.","u":"바닥의 무거운 짐(쌀포대, 아이)을 안전하게 들어 올리는 동작 그 자체. 허리 부상 예방의 핵심 패턴입니다.","st":["발은 골반너비, 바는 발 중앙 위","엉덩이를 뒤로 빼며 바를 잡음(정강이에 가깝게)","가슴을 들고 등을 평평하게, 광배에 힘","발로 바닥을 밀며 바를 몸에 붙여 올림","엉덩이를 앞으로 밀어 똑바로 선 뒤, 같은 경로로 내림"],"c":["허리가 둥글게 말리지 않게","바가 몸에서 멀어지지 않게","처음엔 가벼운 무게로 자세부터"],"cat":"등","p":["glutes","hamstrings","lowerback"],"s":["quads","traps","forearms"]},
{"id":"rackpull","n":"랙풀","en":"Rack Pull","eq":"바벨·파워랙","a":"무릎 높이의 랙에서 바를 들어 올리는 부분 데드리프트로, 등 상부·승모근과 잠그는 힘을 고중량으로 단련합니다.","st":["핀을 무릎 바로 아래 높이에 설정","바를 어깨너비로 잡고 등을 평평하게","엉덩이를 앞으로 밀며 똑바로 섬","천천히 핀 위로 내려놓음"],"c":["마지막에 허리를 뒤로 젖히지 않기","스트랩 사용 가능"],"cat":"등","p":["lowerback","traps","glutes"],"s":["hamstrings","forearms","lats"]},
{"id":"backext","n":"백 익스텐션","en":"Back Extension","eq":"45° 벤치","a":"엉덩이를 축으로 상체를 숙였다 펴는 동작으로, 척추기립근과 둔근·햄스트링을 함께 강화해 허리를 튼튼하게 합니다.","st":["패드에 골반이 걸치도록 높이 조절","상체를 앞으로 천천히 숙임","엉덩이에 힘을 주며 몸이 일직선이 될 때까지 올라옴","천천히 내려감"],"c":["위에서 허리를 과하게 젖히지 않기","반동 금지"],"cat":"등","p":["lowerback"],"s":["glutes","hamstrings"]},
{"id":"goodmorning","n":"굿모닝","en":"Good Morning","eq":"바벨","a":"바를 등에 지고 엉덩이를 뒤로 빼며 숙이는 고관절 힌지 운동으로, 햄스트링과 척추기립근을 단련합니다.","st":["바를 승모근 위에 얹고 섬","무릎을 살짝 굽힌 채 엉덩이를 뒤로 뺌","상체가 바닥과 거의 평행할 때까지 숙임","엉덩이를 앞으로 밀며 일어섬"],"c":["가벼운 무게로 시작","허리가 둥글게 말리지 않게"],"cat":"등","p":["hamstrings","lowerback"],"s":["glutes"]},
{"id":"shrug","n":"바벨 슈러그","en":"Barbell Shrug","eq":"바벨","a":"어깨를 귀 쪽으로 으쓱 올리는 거상 동작으로, 상부 승모근을 키워 목·어깨 라인을 두껍게 만듭니다.","st":["바를 어깨너비로 잡고 섬","팔을 편 채 어깨를 귀 쪽으로 최대한 올림","1초 정지","천천히 내림"],"c":["어깨를 돌리지 말고 위아래로만","목을 앞으로 빼지 않기"],"cat":"등","p":["traps"],"s":["forearms"]},
{"id":"invrow","n":"인버티드 로우","en":"Inverted Row","eq":"스미스머신·바","a":"낮은 바에 매달려 몸을 일직선으로 유지한 채 가슴을 바로 당기는 맨몸 로우입니다.","st":["허리 높이의 바 아래로 누워 바를 잡음","발뒤꿈치를 대고 몸을 일직선으로","가슴을 바에 붙이듯 당김","천천히 내려옴"],"c":["엉덩이가 처지지 않게","어깨를 으쓱하지 않기"],"cat":"등","p":["lats","traps"],"s":["biceps","abs"]},
{"id":"ohp","n":"숄더 프레스","en":"Overhead Press","eq":"바벨·덤벨·머신","a":"팔을 머리 위로 들어 올리는 어깨 굴곡·외전 동작으로 전면·측면 삼각근이 주로 쓰입니다. 위쪽에서는 상부 승모근과 전거근이 어깨뼈를 위로 돌려 공간을 만들고, 삼두근이 팔꿈치를 폅니다.","u":"머리 위 선반에 짐 올리기, 아이 들어 올리기. 어깨 근력과 안정성의 기본입니다.","st":["덤벨(바)을 어깨 높이에서 시작, 손목은 팔꿈치 바로 위","복부와 엉덩이에 힘을 줘 허리 고정","숨을 내쉬며 머리 위로 밀어 올림","귀 옆을 지나 천천히 어깨 높이로 복귀"],"c":["허리를 과하게 젖히지 않기","어깨 통증이 있으면 가동범위를 줄임"],"cat":"어깨","p":["delts"],"s":["triceps","traps"]},
{"id":"dbshoulder","n":"덤벨 숄더프레스","en":"Dumbbell Shoulder Press","eq":"덤벨·벤치","a":"앉아서 덤벨을 머리 위로 밀어 올리는 기본 어깨 운동으로, 삼각근 전면·측면을 고르게 씁니다.","st":["등받이를 세우고 덤벨을 귀 옆에 둠","팔꿈치가 손목 바로 아래 오게","머리 위로 밀어 올리며 살짝 모음","귀 높이까지 천천히 내림"],"c":["허리를 과하게 젖히지 않기","덤벨을 너무 낮게 내리지 않기"],"cat":"어깨","p":["delts"],"s":["triceps","traps"]},
{"id":"arnold","n":"아놀드 프레스","en":"Arnold Press","eq":"덤벨·벤치","a":"손바닥이 나를 향한 상태에서 돌려 밀어 올리는 숄더프레스로, 전면·측면 삼각근을 넓은 범위로 자극합니다.","st":["덤벨을 턱 앞에 손바닥이 나를 보게 듦","팔을 바깥으로 벌리며 손바닥을 앞으로 돌림","머리 위로 밀어 올림","역순으로 돌아옴"],"c":["회전은 부드럽게","무게를 가볍게 시작"],"cat":"어깨","p":["delts"],"s":["triceps"]},
{"id":"mshoulder","n":"머신 숄더프레스","en":"Machine Shoulder Press","eq":"머신","a":"궤적이 고정된 머신으로 안정적으로 삼각근에 집중할 수 있어 입문자에게 좋습니다.","st":["손잡이가 어깨 높이가 되도록 의자 조절","등을 붙이고 손잡이를 잡음","머리 위로 밀어 올림","어깨 높이까지 천천히 내림"],"c":["팔꿈치를 완전히 잠그지 않기","허리 아치 과도 금지"],"cat":"어깨","p":["delts"],"s":["triceps"]},
{"id":"lateral","n":"사이드 레터럴 레이즈","en":"Lateral Raise","eq":"덤벨·케이블","a":"팔을 옆으로 드는 어깨 외전 동작으로 측면 삼각근을 고립시킵니다. 측면 삼각근이 발달하면 어깨가 넓어 보여 상체 비율이 좋아집니다.","u":"팔을 옆으로 들어 물건을 잡는 동작. 넓은 어깨 라인을 만드는 핵심 운동입니다.","st":["덤벨을 몸 옆에 두고 상체를 살짝 숙임","팔꿈치를 살짝 굽혀 고정","새끼손가락 쪽이 약간 위를 향하게 옆으로 들어 올림","어깨 높이까지 올린 뒤 천천히 내림"],"c":["반동으로 던지듯 올리지 않기","어깨가 으쓱 올라가면 승모근 운동이 됨 → 무게를 낮춤"],"cat":"어깨","p":["delts"],"s":["traps"]},
{"id":"cablelat","n":"케이블 레터럴 레이즈","en":"Cable Lateral Raise","eq":"케이블","a":"케이블은 동작 내내 장력이 유지돼, 덤벨보다 낮은 구간에서도 측면 삼각근을 계속 자극합니다.","st":["케이블 옆에 서서 반대손으로 손잡이를 잡음","팔꿈치를 살짝 굽힘","어깨 높이까지 옆으로 들어 올림","천천히 내림"],"c":["몸을 기울여 반동 쓰지 않기","어깨를 으쓱하지 않기"],"cat":"어깨","p":["delts"],"s":["traps"]},
{"id":"frontraise","n":"프론트 레이즈","en":"Front Raise","eq":"덤벨","a":"팔을 앞으로 어깨 높이까지 드는 동작으로 전면 삼각근을 고립시킵니다.","st":["덤벨을 허벅지 앞에 듦","팔꿈치를 살짝 굽힘","어깨 높이까지 앞으로 들어 올림","천천히 내림"],"c":["몸을 뒤로 젖히지 않기","어깨 높이 이상 들지 않기"],"cat":"어깨","p":["delts"],"s":["chest","traps"]},
{"id":"reardelt","n":"벤트오버 리어 델트 레이즈","en":"Bent-Over Rear Delt Raise","eq":"덤벨","a":"상체를 숙이고 팔을 옆으로 벌리는 수평 외전으로, 둥근 어깨 교정에 중요한 후면 삼각근을 단련합니다.","st":["상체를 바닥과 거의 평행하게 숙임","덤벨을 늘어뜨리고 팔꿈치를 살짝 굽힘","날개처럼 옆으로 벌려 올림","천천히 내림"],"c":["등 근육이 아닌 어깨 뒤로 드는 느낌","반동 금지"],"cat":"어깨","p":["delts"],"s":["traps"]},
{"id":"revpec","n":"리버스 펙덱","en":"Reverse Pec Deck","eq":"머신","a":"가슴을 패드에 대고 팔을 뒤로 벌리는 머신 운동으로, 후면 삼각근을 안정적으로 고립합니다.","st":["가슴을 패드에 대고 앉음","손잡이를 어깨 높이로 잡음","팔을 편 채 뒤로 벌림","천천히 모음"],"c":["어깨를 으쓱하지 않기","등을 쥐어짜지 않기"],"cat":"어깨","p":["delts"],"s":["traps"]},
{"id":"facepull","n":"페이스풀","en":"Face Pull","eq":"케이블","a":"로프를 얼굴 쪽으로 당기며 팔을 바깥으로 돌리는(외회전) 동작으로 후면 삼각근, 중·하부 승모근, 회전근개(극하근·소원근)를 강화합니다. 미는 운동으로 앞쪽에 쏠린 어깨 균형을 맞춰줍니다.","u":"거북목·말린 어깨 개선, 어깨 부상 예방. 데스크워커에게 특히 추천합니다.","st":["케이블을 눈높이에 맞추고 로프를 엄지가 뒤로 오게 잡음","팔꿈치를 높게 유지하며 로프를 이마 쪽으로 당김","당기는 끝에서 손을 귀 옆으로 벌리며 바깥으로 돌림","1초 정지 후 천천히 복귀"],"c":["허리를 젖히며 당기지 않기","가벼운 무게로 정확하게"],"cat":"어깨","p":["delts","traps"],"s":["biceps"]},
{"id":"uprow","n":"업라이트 로우","en":"Upright Row","eq":"바벨","a":"바를 몸에 붙여 턱 아래까지 끌어올리는 동작으로, 측면 삼각근과 승모근을 함께 씁니다.","st":["바를 어깨너비로 잡음","팔꿈치를 바깥 위로 들어 올림","가슴 높이까지 끌어올림","천천히 내림"],"c":["어깨가 불편하면 손 간격을 넓히기","너무 높이 당기지 않기"],"cat":"어깨","p":["delts","traps"],"s":["biceps"]},
{"id":"dbshrug","n":"덤벨 슈러그","en":"Dumbbell Shrug","eq":"덤벨","a":"덤벨을 들고 어깨를 으쓱 올려 상부 승모근을 키웁니다.","st":["덤벨을 몸 옆에 듦","어깨를 귀 쪽으로 올림","1초 정지","천천히 내림"],"c":["어깨를 돌리지 않기","턱을 당겨 목 중립"],"cat":"어깨","p":["traps"],"s":["forearms"]},
{"id":"curl","n":"바벨 컬","en":"Barbell Curl","eq":"바벨·덤벨","a":"팔꿈치를 굽히는 굴곡 동작으로 상완이두근과 그 아래 상완근, 전완의 상완요골근이 함께 일합니다. 이두근은 손바닥을 위로 돌리는 회외 동작도 담당합니다.","u":"장바구니 들기, 아이 안아 올리기, 물건 당겨 들기. 팔 앞쪽 라인을 만듭니다.","st":["어깨너비로 바를 손바닥이 앞을 보게 잡음","팔꿈치를 옆구리에 고정","팔꿈치만 굽혀 바를 가슴 쪽으로 올림","이두근을 쥐어짜고 천천히 내림"],"c":["상체 반동 금지","팔꿈치가 앞으로 나가지 않게"],"cat":"이두","p":["biceps"],"s":["forearms"]},
{"id":"dbcurl","n":"덤벨 컬","en":"Dumbbell Curl","eq":"덤벨","a":"손바닥을 위로 돌리며(회외) 팔꿈치를 굽히는 동작으로, 상완이두근을 좌우 따로 단련합니다.","st":["덤벨을 손바닥이 앞을 보게 듦","팔꿈치를 옆구리에 고정","어깨 쪽으로 감아 올림","천천히 내림"],"c":["팔꿈치가 앞으로 나가지 않게","몸 반동 금지"],"cat":"이두","p":["biceps"],"s":["forearms"]},
{"id":"hammer","n":"해머 컬","en":"Hammer Curl","eq":"덤벨","a":"손바닥이 마주 보는 망치 잡기로 굽혀, 상완근과 위팔노근(전완)까지 두껍게 키웁니다.","st":["덤벨을 손바닥이 몸을 향하게 듦","팔꿈치를 고정","망치를 들듯 들어 올림","천천히 내림"],"c":["손목을 꺾지 않기","반동 금지"],"cat":"이두","p":["biceps","forearms"],"s":[]},
{"id":"preacher","n":"프리처 컬","en":"Preacher Curl","eq":"EZ바·프리처 벤치","a":"팔 뒤를 경사 패드에 고정해 반동을 없애고, 이두근의 늘어난 구간을 집중 자극합니다.","st":["겨드랑이를 패드 위에 걸치고 앉음","바를 어깨너비로 잡음","팔꿈치를 고정하고 감아 올림","팔이 거의 펴질 때까지 천천히 내림"],"c":["맨 아래에서 팔꿈치를 완전히 잠그지 않기","어깨가 들리지 않게"],"cat":"이두","p":["biceps"],"s":["forearms"]},
{"id":"inccurl","n":"인클라인 덤벨 컬","en":"Incline Dumbbell Curl","eq":"덤벨·인클라인 벤치","a":"등을 기대고 팔을 뒤로 늘어뜨린 상태에서 컬을 해, 이두근 장두를 크게 늘여 자극합니다.","st":["벤치를 45° 정도로 세우고 기댐","팔을 자연스럽게 늘어뜨림","팔꿈치 위치를 유지하며 감아 올림","천천히 내림"],"c":["어깨가 앞으로 나오지 않게","가벼운 무게로"],"cat":"이두","p":["biceps"],"s":["forearms"]},
{"id":"conccurl","n":"컨센트레이션 컬","en":"Concentration Curl","eq":"덤벨·벤치","a":"팔꿈치를 허벅지 안쪽에 고정해 오직 이두근만 쓰도록 하는 고립 운동입니다.","st":["벤치에 앉아 다리를 벌림","팔꿈치를 허벅지 안쪽에 댐","덤벨을 어깨 쪽으로 감아 올림","천천히 내림"],"c":["상체를 들어 올리지 않기","손목 고정"],"cat":"이두","p":["biceps"],"s":["forearms"]},
{"id":"cablecurl","n":"케이블 컬","en":"Cable Curl","eq":"케이블","a":"케이블이 동작 내내 일정한 장력을 줘 이두근을 끝까지 수축시키기 좋습니다.","st":["낮은 도르래 앞에 서서 바를 잡음","팔꿈치를 옆구리에 고정","감아 올려 1초 쥐어짬","천천히 내림"],"c":["몸을 뒤로 젖히지 않기","팔꿈치 고정"],"cat":"이두","p":["biceps"],"s":["forearms"]},
{"id":"pushdown","n":"케이블 푸시다운","en":"Triceps Pushdown","eq":"케이블","a":"팔꿈치를 펴는 신전 동작으로 상완삼두근(외측·내측·장두)을 고립시킵니다. 삼두근은 팔 둘레의 약 2/3를 차지해 팔 굵기에 가장 큰 영향을 줍니다.","u":"바닥 짚고 일어나기, 미는 동작의 마무리 힘. 벤치프레스 기록 향상에도 도움.","st":["케이블 앞에 서서 바(로프)를 잡음","팔꿈치를 옆구리에 붙여 고정","팔꿈치만 펴서 아래로 끝까지 밀어냄","삼두근을 수축한 뒤 천천히 복귀"],"c":["팔꿈치가 벌어지거나 앞뒤로 움직이지 않게","상체로 누르지 않기"],"cat":"삼두","p":["triceps"],"s":[]},
{"id":"ropepush","n":"로프 푸시다운","en":"Rope Pushdown","eq":"케이블·로프","a":"로프를 쓰면 마지막에 손을 바깥으로 벌려 삼두근 외측두를 더 강하게 수축시킬 수 있습니다.","st":["로프를 잡고 팔꿈치를 옆구리에 붙임","팔을 펴며 아래로 내림","마지막에 로프를 양옆으로 벌림","천천히 돌아옴"],"c":["팔꿈치가 앞뒤로 움직이지 않게","상체로 누르지 않기"],"cat":"삼두","p":["triceps"],"s":["forearms"]},
{"id":"skull","n":"라잉 트라이셉스 익스텐션","en":"Lying Triceps Extension (Skull Crusher)","eq":"EZ바·벤치","a":"팔꿈치를 고정하고 바를 이마 쪽으로 내렸다 펴, 삼두근 장두까지 크게 늘여 단련합니다.","st":["벤치에 누워 바를 가슴 위로 듦","팔꿈치를 고정하고 이마 뒤쪽으로 내림","삼두근으로 팔을 펴 올림","팔꿈치가 벌어지지 않게 유지"],"c":["팔꿈치 통증 시 무게 줄이기","보조자 권장"],"cat":"삼두","p":["triceps"],"s":[]},
{"id":"ohext","n":"오버헤드 트라이셉스 익스텐션","en":"Overhead Triceps Extension","eq":"덤벨","a":"팔을 머리 위로 올린 자세라 삼두근 장두가 크게 늘어나, 팔 뒤쪽 볼륨을 키우기 좋습니다.","st":["덤벨 한 개를 양손으로 머리 위에 듦","팔꿈치를 귀 옆에 고정","머리 뒤로 천천히 내림","팔을 펴 올림"],"c":["팔꿈치가 벌어지지 않게","허리를 젖히지 않기"],"cat":"삼두","p":["triceps"],"s":[]},
{"id":"cgbench","n":"클로즈그립 벤치프레스","en":"Close-Grip Bench Press","eq":"바벨·벤치","a":"손 간격을 어깨너비로 좁혀 팔꿈치를 몸에 붙인 채 미는 벤치프레스로, 삼두근에 큰 무게를 줄 수 있습니다.","st":["어깨너비로 바를 잡음","팔꿈치를 몸통 가까이 붙여 내림","가슴 아래쪽에 닿을 듯 내림","삼두로 밀어 올림"],"c":["손 간격을 너무 좁히면 손목 부담","팔꿈치를 벌리지 않기"],"cat":"삼두","p":["triceps"],"s":["chest","delts"]},
{"id":"kickback","n":"덤벨 킥백","en":"Dumbbell Kickback","eq":"덤벨","a":"상체를 숙이고 위팔을 몸통에 고정한 채 뒤로 펴, 삼두근을 끝까지 수축시킵니다.","st":["상체를 숙이고 위팔을 몸통과 나란히","팔꿈치를 고정","뒤로 팔을 쭉 폄","천천히 굽힘"],"c":["위팔이 내려가지 않게","가벼운 무게로"],"cat":"삼두","p":["triceps"],"s":[]},
{"id":"benchdip","n":"벤치 딥스","en":"Bench Dip","eq":"벤치","a":"벤치에 손을 짚고 몸을 내렸다 올리는 맨몸 삼두 운동입니다.","st":["벤치 끝에 손을 짚고 다리를 앞으로 뻗음","팔꿈치를 뒤로 굽히며 엉덩이를 내림","팔꿈치 90°까지","손바닥으로 밀어 올라옴"],"c":["어깨가 앞으로 쏠리지 않게","엉덩이를 벤치 가까이"],"cat":"삼두","p":["triceps"],"s":["chest","delts"]},
{"id":"cableohext","n":"케이블 오버헤드 익스텐션","en":"Cable Overhead Extension","eq":"케이블·로프","a":"케이블을 등지고 머리 위로 팔을 펴, 늘어난 자세에서 삼두근 장두를 강하게 씁니다.","st":["케이블을 등지고 로프를 머리 뒤로 잡음","상체를 살짝 숙이고 팔꿈치를 귀 옆에","앞으로 팔을 쭉 폄","천천히 굽힘"],"c":["팔꿈치가 벌어지지 않게","허리 중립"],"cat":"삼두","p":["triceps"],"s":[]},
{"id":"wristcurl","n":"리스트 컬","en":"Wrist Curl","eq":"바벨·벤치","a":"손목만 굽혔다 펴 손목 굴곡근(전완 앞쪽)을 단련해 악력을 키웁니다.","st":["벤치에 앉아 전완을 허벅지 위에 올림","손바닥이 위를 보게 바를 잡음","손목을 아래로 늘였다가","손목만 위로 말아 올림"],"c":["팔꿈치가 들리지 않게","가벼운 무게로 고반복"],"cat":"전완","p":["forearms"],"s":[]},
{"id":"revwrist","n":"리버스 리스트 컬","en":"Reverse Wrist Curl","eq":"바벨·벤치","a":"손등이 위를 보게 잡고 손목을 젖혀 전완 바깥쪽(신전근)을 강화해, 팔꿈치 통증 예방에 도움이 됩니다.","st":["전완을 허벅지에 얹고 손등이 위","손목을 아래로 떨어뜨림","손목만 위로 젖혀 올림","천천히 내림"],"c":["매우 가벼운 무게로","반동 금지"],"cat":"전완","p":["forearms"],"s":[]},
{"id":"revcurl","n":"리버스 컬","en":"Reverse Curl","eq":"바벨","a":"손등이 위를 보게 잡고 컬을 해 위팔노근과 전완 신전근을 키웁니다.","st":["손등이 앞을 보게 바를 잡음","팔꿈치 고정","감아 올림","천천히 내림"],"c":["손목을 꺾지 않기","가벼운 무게로"],"cat":"전완","p":["forearms","biceps"],"s":[]},
{"id":"farmer","n":"파머스 워크","en":"Farmer's Walk","eq":"덤벨·케틀벨","a":"무거운 무게를 들고 걷는 운동으로, 악력·승모근·코어를 동시에 강화하는 기능성 운동입니다.","st":["무거운 덤벨을 양손에 듦","가슴을 펴고 어깨를 내림","짧고 빠른 보폭으로 걸음","정해진 거리·시간 후 내려놓음"],"c":["허리를 굽혀 들지 않기","몸이 좌우로 흔들리지 않게"],"cat":"전완","p":["forearms","traps"],"s":["glutes","quads","abs"]},
{"id":"squat","n":"스쿼트","en":"Back Squat","eq":"바벨","a":"무릎·엉덩이·발목이 동시에 굽혔다 펴지는 다관절 운동입니다. 대퇴사두근이 무릎을 펴고, 대둔근과 내전근이 엉덩관절을 펴며 일어섭니다. 척추기립근과 복부는 몸통을 단단히 고정합니다.","u":"의자에서 일어나기, 계단 오르기, 쪼그려 앉았다 일어나기 등 하체 기능 전반. \"운동의 왕\"이라 불리는 기본 패턴입니다.","st":["바를 승모근 위에 올리고 발은 어깨너비, 발끝 약간 바깥","숨을 들이마셔 배에 압력을 채움","엉덩이를 뒤·아래로 내리며 무릎은 발끝 방향","허벅지가 바닥과 평행(또는 가능한 깊이)까지","발 전체로 바닥을 밀며 일어남"],"c":["무릎이 안쪽으로 모이지 않게","뒤꿈치가 뜨지 않게","허리가 말리는 깊이 전에서 멈춤"],"cat":"하체","p":["quads","glutes"],"s":["adductors","hamstrings","lowerback","abs"]},
{"id":"frontsquat","n":"프론트 스쿼트","en":"Front Squat","eq":"바벨","a":"바를 어깨 앞에 얹어 상체가 더 서 있게 되므로 대퇴사두근 비중이 크고 허리 부담이 적습니다.","st":["바를 쇄골 위 어깨 앞에 얹고 팔꿈치를 높게","발을 어깨너비로","상체를 세운 채 깊게 앉음","발바닥 전체로 밀며 일어섬"],"c":["팔꿈치가 떨어지면 바가 앞으로 쏠림","무릎이 안으로 모이지 않게"],"cat":"하체","p":["quads"],"s":["glutes","abs"]},
{"id":"goblet","n":"고블릿 스쿼트","en":"Goblet Squat","eq":"덤벨·케틀벨","a":"덤벨을 가슴 앞에 들고 앉는 스쿼트로, 자연스럽게 상체가 세워져 스쿼트 자세를 배우기 가장 좋습니다.","st":["덤벨을 가슴 앞에 세로로 받쳐 듦","발을 어깨너비보다 살짝 넓게","팔꿈치가 무릎 안쪽을 지나도록 깊게 앉음","일어섬"],"c":["뒤꿈치가 뜨지 않게","허리 중립"],"cat":"하체","p":["quads","glutes"],"s":["abs","adductors"]},
{"id":"hack","n":"핵 스쿼트","en":"Hack Squat","eq":"머신","a":"등을 패드에 기대고 레일을 따라 앉는 머신 스쿼트로, 균형 부담 없이 대퇴사두근에 집중합니다.","st":["등과 어깨를 패드에 붙임","발판에 어깨너비로 발을 둠","무릎을 굽혀 깊게 내려감","발바닥으로 밀어 올라옴"],"c":["무릎을 완전히 잠그지 않기","엉덩이가 패드에서 떨어지지 않게"],"cat":"하체","p":["quads"],"s":["glutes"]},
{"id":"smithsquat","n":"스미스 스쿼트","en":"Smith Machine Squat","eq":"스미스머신","a":"바가 레일에 고정돼 균형을 잡을 필요가 적어, 하체에 집중하거나 발 위치를 바꿔 자극을 조절하기 좋습니다.","st":["바 아래 승모근에 얹고 걸쇠를 풀기","발을 살짝 앞에 둠","깊게 앉음","밀어 올라옴"],"c":["세이프티 높이 설정","무릎이 안으로 모이지 않게"],"cat":"하체","p":["quads","glutes"],"s":["hamstrings"]},
{"id":"legpress","n":"레그프레스","en":"Leg Press","eq":"머신","a":"등이 지지된 상태에서 발판을 밀어 무릎과 엉덩관절을 폅니다. 허리 부담이 적어 하체 근육에 고중량을 안전하게 줄 수 있습니다. 발 위치가 높고 넓을수록 둔근·햄스트링, 낮고 좁을수록 대퇴사두근 비중이 커집니다.","u":"스쿼트가 어려운 분의 하체 강화, 계단·등산 체력.","st":["등과 엉덩이를 패드에 밀착","발은 어깨너비로 발판 중앙","안전장치 해제 후 무릎을 가슴 쪽으로 천천히 굽힘","엉덩이가 들리기 전까지 내린 뒤 밀어냄"],"c":["무릎을 완전히 펴서 잠그지 않기","엉덩이가 패드에서 떨어지지 않게"],"cat":"하체","p":["quads","glutes"],"s":["hamstrings","adductors"]},
{"id":"lunge","n":"런지","en":"Lunge","eq":"맨몸·덤벨","a":"한쪽 다리로 체중을 받는 편측 운동으로 앞다리의 대퇴사두근·둔근이 주로 일하고, 중둔근·내전근이 골반과 무릎을 안정시킵니다. 좌우 불균형 교정과 균형감각에 좋습니다.","u":"걷기, 계단 오르기, 한 발로 버티기. 낙상 예방과 운동 능력 향상.","st":["발을 골반너비로 서서 한 발 앞으로 크게 내딛음","상체를 세운 채 뒷무릎이 바닥 가까이 갈 때까지 내려감","앞발 뒤꿈치로 밀며 올라옴","다리를 바꿔 반복"],"c":["앞무릎이 안쪽으로 무너지지 않게","보폭이 너무 좁지 않게"],"cat":"하체","p":["quads","glutes"],"s":["adductors","hamstrings","calves"]},
{"id":"bulgarian","n":"불가리안 스플릿 스쿼트","en":"Bulgarian Split Squat","eq":"덤벨·벤치","a":"뒷발을 벤치에 올린 한 다리 스쿼트로, 앞다리 대퇴사두근·둔근을 강하게 쓰고 좌우 균형을 맞춥니다.","st":["벤치 앞 60~90cm에 서서 뒷발 등을 벤치에 올림","상체를 세우고 덤벨을 듦","뒷무릎이 바닥에 가까워질 때까지 내려감","앞발 뒤꿈치로 밀어 올라옴"],"c":["앞무릎이 안으로 모이지 않게","균형이 어려우면 맨몸부터"],"cat":"하체","p":["quads","glutes"],"s":["hamstrings","adductors"]},
{"id":"stepup","n":"스텝업","en":"Step-up","eq":"박스·덤벨","a":"박스에 한 발로 올라서는 동작으로, 계단 오르기 힘을 키우고 한쪽 다리 근력·균형을 기릅니다.","st":["무릎 높이 박스 앞에 섬","한 발을 박스 전체에 올림","앞발 뒤꿈치로 밀어 올라섬","천천히 내려옴"],"c":["뒷발로 튕기지 않기","무릎이 안으로 모이지 않게"],"cat":"하체","p":["quads","glutes"],"s":["hamstrings","calves"]},
{"id":"legext","n":"레그 익스텐션","en":"Leg Extension","eq":"머신","a":"무릎을 펴는 동작만으로 대퇴사두근을 고립시킵니다. 특히 무릎 바로 위 안쪽의 내측광근 강화로 무릎 안정성에 도움이 됩니다.","u":"계단 내려가기, 공 차기. 허벅지 앞 라인 정리.","st":["등받이와 패드를 무릎 축에 맞춤","발목 위에 패드가 오게 앉음","무릎을 끝까지 펴고 1초 정지","천천히 내림"],"c":["반동 금지","무릎 통증 시 가동범위 조절"],"cat":"하체","p":["quads"],"s":[]},
{"id":"legcurl","n":"레그 컬","en":"Leg Curl","eq":"머신","a":"무릎을 굽히는 굴곡 동작으로 햄스트링을 고립시킵니다. 대퇴사두근과 햄스트링의 근력 균형은 무릎·햄스트링 부상 예방에 중요합니다.","u":"달리기에서 다리 끌어당기기, 무릎 보호.","st":["머신에 엎드리거나 앉아 패드를 발목 뒤에 맞춤","엉덩이가 뜨지 않게 고정","발꿈치를 엉덩이 쪽으로 당김","천천히 펴며 복귀"],"c":["엉덩이를 들어 올리는 보상 금지"],"cat":"하체","p":["hamstrings"],"s":["calves"]},
{"id":"seatedcurl","n":"시티드 레그 컬","en":"Seated Leg Curl","eq":"머신","a":"앉은 자세에서 무릎을 굽히는 레그 컬로, 햄스트링이 늘어난 상태에서 일해 근성장에 효과적입니다.","st":["무릎이 회전축과 맞도록 앉음","허벅지 패드로 다리 고정","뒤꿈치를 엉덩이 쪽으로 당김","천천히 폄"],"c":["엉덩이가 들리지 않게","반동 금지"],"cat":"하체","p":["hamstrings"],"s":["calves"]},
{"id":"rdl","n":"루마니안 데드리프트","en":"Romanian Deadlift","eq":"바벨·덤벨","a":"무릎 각도를 거의 고정한 채 엉덩이를 뒤로 빼는 힙힌지로 햄스트링이 길게 늘어난 상태에서 힘을 냅니다. 햄스트링과 대둔근이 엉덩관절을 펴며 올라옵니다.","u":"허리를 숙여 물건 줍기, 달리기·점프의 추진력. 허벅지 뒤 라인과 힙업에 효과적.","st":["바를 들고 서서 무릎을 살짝 굽힘","엉덩이를 뒤로 밀며 바를 허벅지를 따라 내림","허벅지 뒤가 당기면(보통 정강이 중간) 멈춤","엉덩이를 앞으로 밀며 올라옴"],"c":["등이 둥글게 말리지 않게","바가 몸에서 떨어지지 않게"],"cat":"하체","p":["hamstrings","glutes"],"s":["lowerback","forearms"]},
{"id":"sldl","n":"스티프 레그 데드리프트","en":"Stiff-Leg Deadlift","eq":"바벨","a":"무릎을 거의 편 채 상체를 숙여 햄스트링을 최대로 늘이는 데드리프트 변형입니다.","st":["바를 허벅지 앞에 듦","무릎을 거의 편 채 엉덩이를 뒤로","햄스트링이 당길 때까지 숙임","엉덩이를 밀며 일어섬"],"c":["허리가 말리기 전까지만 내려가기","가벼운 무게로"],"cat":"하체","p":["hamstrings"],"s":["glutes","lowerback"]},
{"id":"sumo","n":"스모 데드리프트","en":"Sumo Deadlift","eq":"바벨","a":"발을 넓게 벌리고 손은 다리 안쪽을 잡는 데드리프트로, 상체가 서 있어 허리 부담이 적고 둔근·내전근을 많이 씁니다.","st":["발을 어깨너비 2배로 벌리고 발끝을 바깥으로","다리 안쪽으로 바를 잡음","무릎을 바깥으로 밀며 가슴을 듦","엉덩이를 밀며 일어섬"],"c":["무릎이 안으로 모이지 않게","허리 중립"],"cat":"하체","p":["glutes","quads","adductors"],"s":["hamstrings","lowerback","traps"]},
{"id":"adductor","n":"이너 싸이 (어덕션 머신)","en":"Hip Adduction Machine","eq":"머신","a":"벌어진 다리를 안쪽으로 모으는 머신으로, 허벅지 안쪽 내전근을 강화해 무릎·골반 안정성을 높입니다.","st":["무릎 안쪽에 패드가 오도록 앉음","등을 붙이고 손잡이를 잡음","다리를 안쪽으로 모음","천천히 벌림"],"c":["반동 없이","너무 넓게 벌려 시작하지 않기"],"cat":"하체","p":["adductors"],"s":[]},
{"id":"hipthrust","n":"힙 쓰러스트","en":"Hip Thrust","eq":"바벨·벤치","a":"엉덩관절을 완전히 펴는 끝 범위에서 대둔근이 최대로 수축하도록 설계된 운동입니다. 엉덩이 근육을 가장 직접적으로 강화하는 운동 중 하나입니다.","u":"일어서기, 달리기·점프의 추진력, 골반 안정. 힙업과 허리 통증 예방.","st":["벤치에 날개뼈 아래를 걸치고 바를 골반 위에","발은 골반너비, 무릎 90°가 되게 위치","턱을 당기고 엉덩이를 위로 밀어 올림","상체와 허벅지가 일직선일 때 엉덩이를 꽉 조임","천천히 내림"],"c":["허리를 젖히지 말고 엉덩이로 올리기","바에 패드 사용"],"cat":"엉덩이","p":["glutes"],"s":["hamstrings","quads"]},
{"id":"glutebridge","n":"글루트 브릿지","en":"Glute Bridge","eq":"맨몸·매트","a":"누워서 엉덩이를 들어 올리는 동작으로, 둔근을 활성화하고 허리 통증 예방에 좋은 기본 운동입니다.","st":["누워서 무릎을 세우고 발을 엉덩이 가까이","배에 힘을 줌","엉덩이를 조이며 어깨~무릎이 일직선까지 들어 올림","천천히 내림"],"c":["허리를 젖히지 말고 엉덩이로","발뒤꿈치로 밀기"],"cat":"엉덩이","p":["glutes"],"s":["hamstrings","abs"]},
{"id":"cablekick","n":"케이블 킥백","en":"Cable Kickback","eq":"케이블·발목 스트랩","a":"한 다리를 뒤로 차는 고관절 신전 운동으로, 둔근을 한쪽씩 고립시킵니다.","st":["발목 스트랩을 차고 케이블을 마주 봄","상체를 살짝 숙이고 손잡이를 잡음","무릎을 살짝 굽힌 채 다리를 뒤로 차올림","천천히 돌아옴"],"c":["허리를 젖히지 않기","엉덩이로 미는 느낌"],"cat":"엉덩이","p":["glutes"],"s":["hamstrings"]},
{"id":"abductor","n":"아웃 싸이 (어브덕션 머신)","en":"Hip Abduction Machine","eq":"머신","a":"다리를 바깥으로 벌리는 머신으로, 엉덩이 옆쪽(중둔근)을 강화해 골반과 무릎 정렬을 돕습니다.","st":["무릎 바깥에 패드가 오도록 앉음","등을 붙임","다리를 바깥으로 벌림","천천히 모음"],"c":["상체를 앞으로 숙이면 대둔근, 세우면 중둔근","반동 금지"],"cat":"엉덩이","p":["glutes"],"s":[]},
{"id":"kbswing","n":"케틀벨 스윙","en":"Kettlebell Swing","eq":"케틀벨","a":"엉덩이를 폭발적으로 펴는 힘으로 케틀벨을 띄우는 운동으로, 둔근·햄스트링 파워와 심폐지구력을 함께 기릅니다.","st":["발을 어깨너비보다 넓게, 케틀벨을 두 손으로","엉덩이를 뒤로 빼며 다리 사이로 보냄","엉덩이를 힘차게 앞으로 밀어 가슴 높이까지 띄움","자연스럽게 떨어지며 반복"],"c":["팔로 들지 말고 엉덩이로","스쿼트처럼 앉지 않기"],"cat":"엉덩이","p":["glutes","hamstrings"],"s":["lowerback","delts","abs"]},
{"id":"calf","n":"카프 레이즈","en":"Calf Raise","eq":"머신·맨몸","a":"발목을 펴는 족저굴곡으로 종아리의 비복근과 가자미근을 강화합니다. 무릎을 펴면 비복근, 앉아서 무릎을 굽히면 가자미근 비중이 커집니다.","u":"걷기·달리기의 마지막 밀기, 까치발. 하지 혈액순환(제2의 심장)에도 도움.","st":["발 앞꿈치를 발판 끝에 올림","뒤꿈치를 아래로 충분히 내려 늘림","최대한 높이 까치발로 올라 1초 정지","천천히 내림"],"c":["반동 없이 끝 범위까지"],"cat":"종아리","p":["calves"],"s":[]},
{"id":"seatedcalf","n":"시티드 카프 레이즈","en":"Seated Calf Raise","eq":"머신","a":"무릎을 굽힌 자세에서 발뒤꿈치를 들어, 종아리 안쪽 가자미근을 집중 단련합니다.","st":["무릎 위에 패드를 대고 앉음","발 앞쪽만 발판에 올림","뒤꿈치를 최대한 들어 올림","뒤꿈치를 깊게 내림"],"c":["반동 없이 끝까지","맨 위에서 1초 정지"],"cat":"종아리","p":["calves"],"s":[]},
{"id":"lpcalf","n":"레그프레스 카프 레이즈","en":"Leg Press Calf Raise","eq":"레그프레스 머신","a":"레그프레스에서 다리를 편 채 발목만 밀어, 무거운 무게로 비복근을 단련합니다.","st":["다리를 편 상태로 발 앞쪽만 발판에","무릎을 살짝 굽혀 고정","발끝으로 발판을 밀어냄","천천히 돌아옴"],"c":["안전장치를 풀어두고 발이 미끄러지지 않게","무릎을 굽혔다 폈다 하지 않기"],"cat":"종아리","p":["calves"],"s":[]},
{"id":"plank","n":"플랭크","en":"Plank","eq":"맨몸","a":"움직임 없이 버티는 등척성 운동으로 복직근·복횡근·복사근이 척추가 꺾이지 않도록 지탱합니다. 둔근과 어깨 안정근도 함께 일합니다.","u":"무거운 것을 들 때 허리 보호, 바른 자세 유지. 모든 운동의 기초 코어 근력.","st":["팔꿈치를 어깨 바로 아래에 두고 엎드림","머리~발뒤꿈치 일직선","배꼽을 등 쪽으로 당기고 엉덩이 조임","호흡을 멈추지 않고 버팀"],"c":["허리가 처지거나 엉덩이가 솟지 않게"],"cat":"코어","p":["abs"],"s":["obliques","delts","glutes"]},
{"id":"crunch","n":"크런치","en":"Crunch","eq":"매트","a":"척추를 말아 어깨를 바닥에서 띄우는 동작으로, 복직근 윗부분을 단련합니다.","st":["누워서 무릎을 세우고 손은 귀 옆","배꼽을 바닥 쪽으로 누름","날개뼈가 뜰 때까지 상체를 말아 올림","천천히 내림"],"c":["손으로 목을 당기지 않기","반동 금지"],"cat":"코어","p":["abs"],"s":["obliques"]},
{"id":"cablecrunch","n":"케이블 크런치","en":"Cable Crunch","eq":"케이블","a":"척추를 둥글게 말아 갈비뼈와 골반을 가깝게 하는 굴곡 동작으로 복직근을 자극합니다. 케이블로 무게를 더해 점진적 과부하가 쉽습니다.","u":"누운 자세에서 일어나기, 몸통 굽히기. 복근 선명도 향상.","st":["케이블 앞에 무릎을 꿇고 로프를 머리 옆에 고정","엉덩이는 고정한 채 명치를 배꼽 쪽으로 말아 내림","복부를 쥐어짜고 천천히 복귀"],"c":["팔로 당기지 말고 복부로 말기","엉덩이가 뒤로 앉지 않게"],"cat":"코어","p":["abs"],"s":["obliques"]},
{"id":"legraise","n":"라잉 레그 레이즈","en":"Lying Leg Raise","eq":"매트","a":"누워서 다리를 들어 올려 아랫배(복직근 하부)와 고관절 굴곡근을 단련합니다.","st":["누워서 손을 엉덩이 옆 바닥에 둠","다리를 모아 곧게 폄","다리를 수직까지 들어 올림","바닥에 닿기 직전까지 천천히 내림"],"c":["허리가 뜨면 무릎을 굽혀서","반동 금지"],"cat":"코어","p":["abs"],"s":["obliques"]},
{"id":"hangleg","n":"행잉 레그 레이즈","en":"Hanging Leg Raise","eq":"철봉","a":"철봉에 매달려 다리를 들어 올리는 고강도 복근 운동으로, 악력과 코어를 함께 씁니다.","st":["철봉에 매달려 어깨를 내림","다리를 모음","다리를 수평 이상으로 들어 올림","흔들림 없이 천천히 내림"],"c":["몸이 흔들리면 잠깐 멈추고 다시","어려우면 무릎 굽혀서"],"cat":"코어","p":["abs"],"s":["obliques","forearms"]},
{"id":"russian","n":"러시안 트위스트","en":"Russian Twist","eq":"메디신볼·덤벨","a":"상체를 뒤로 기울인 채 좌우로 비트는 동작으로, 복사근과 몸통 회전 근력을 기릅니다.","st":["앉아서 무릎을 굽히고 상체를 뒤로 45°","공이나 덤벨을 가슴 앞에 듦","몸통을 좌우로 번갈아 비틂","발을 들면 강도 상승"],"c":["팔만 흔들지 말고 몸통을 돌리기","허리가 둥글게 말리지 않게"],"cat":"코어","p":["obliques","abs"],"s":[]},
{"id":"abroll","n":"앱 롤아웃","en":"Ab Wheel Rollout","eq":"앱 롤러","a":"무릎을 꿇고 바퀴를 굴려 몸을 앞으로 뻗었다가 돌아오는 동작으로, 코어 전체를 매우 강하게 씁니다.","st":["무릎을 꿇고 롤러를 어깨 아래에 둠","배에 힘을 주고 엉덩이를 살짝 말기","몸을 일직선으로 유지하며 앞으로 굴림","복부 힘으로 당겨 돌아옴"],"c":["허리가 꺾이면 범위를 줄이기","초보자는 짧게"],"cat":"코어","p":["abs"],"s":["lats","delts"]},
{"id":"mountain","n":"마운틴 클라이머","en":"Mountain Climber","eq":"맨몸","a":"푸시업 자세에서 무릎을 번갈아 가슴으로 당기는 운동으로, 코어와 심폐지구력을 함께 기릅니다.","st":["팔을 편 푸시업 자세","한쪽 무릎을 가슴 쪽으로 당김","빠르게 다리를 바꿈","정해진 시간 반복"],"c":["엉덩이가 들리지 않게","어깨는 손목 바로 위"],"cat":"코어","p":["abs"],"s":["quads","delts","obliques"]},
{"id":"deadbug","n":"데드버그","en":"Dead Bug","eq":"매트","a":"누워서 팔다리를 반대로 뻗는 동작으로, 허리를 바닥에 붙인 채 코어 안정성을 기르는 재활·기초 운동입니다.","st":["누워서 팔은 위로, 무릎은 90°로 듦","허리를 바닥에 붙임","한쪽 팔과 반대쪽 다리를 천천히 뻗음","돌아와 반대로"],"c":["허리가 뜨지 않게","숨을 참지 않기"],"cat":"코어","p":["abs"],"s":["obliques"]},
{"id":"situp","n":"싯업","en":"Sit-up","eq":"매트","a":"상체를 완전히 일으키는 복근 운동으로, 복직근과 고관절 굴곡근을 함께 씁니다.","st":["누워서 무릎을 세움","손은 가슴이나 귀 옆","상체를 말아 올려 앉음","천천히 누움"],"c":["목을 당기지 않기","허리 통증 시 크런치로"],"cat":"코어","p":["abs"],"s":["obliques"]},
{"id":"thruster","n":"쓰러스터","en":"Thruster","eq":"바벨·덤벨","a":"프론트 스쿼트로 앉았다 일어나는 힘으로 바를 머리 위까지 밀어 올리는 전신 운동입니다.","st":["바를 어깨 앞에 얹고 섬","프론트 스쿼트로 깊게 앉음","일어나는 힘을 이용해 바를 머리 위로","바를 어깨로 내리며 다시 앉음"],"c":["허리를 젖히며 밀지 않기","가벼운 무게로 리듬 익히기"],"cat":"전신","p":["quads","delts","glutes"],"s":["triceps","abs"]},
{"id":"rowerg","n":"로잉머신","en":"Rowing Machine","eq":"로잉 머신","a":"다리로 밀고, 몸을 젖히고, 팔로 당기는 순서의 전신 유산소 운동으로 하체·등·심폐를 함께 단련합니다.","st":["발을 고정하고 무릎을 굽혀 손잡이를 잡음","다리로 먼저 밀어냄","상체를 살짝 젖히며 손잡이를 명치로 당김","역순(팔→몸→다리)으로 돌아감"],"c":["팔로만 당기지 않기","허리를 둥글게 말지 않기"],"cat":"전신","p":["lats","quads"],"s":["hamstrings","glutes","biceps","abs"]}];
